import{_ as t,o as d,c as o,a2 as i}from"./chunks/framework.Ch4PdLd_.js";const u=JSON.parse('{"title":"OpenTUI 界面（实验）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/opentui.md","filePath":"guide/opentui.md"}'),c={name:"guide/opentui.md"};function a(r,e,n,s,l,p){return d(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="opentui-界面-实验" tabindex="-1">OpenTUI 界面（实验） <a class="header-anchor" href="#opentui-界面-实验" aria-label="Permalink to &quot;OpenTUI 界面（实验）&quot;">​</a></h1><p><code>nek --ui opentui</code> 启动一个基于 <a href="https://opentui.com" target="_blank" rel="noreferrer">OpenTUI</a>（<code>@opentui/core</code>）的新终端界面。原来的界面仍是默认，不受影响。</p><p>新界面的目标是与原界面功能完全对齐，只在外观上增强：主题派生的分层背景、圆角对话框、弱化的次要文字。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ul><li><p><strong>Bun 1.3 或更高版本</strong>。OpenTUI 通过 Bun FFI 加载原生核心，不能在 Node 上运行。nek 按以下顺序查找 Bun：</p><ol><li>环境变量 <code>NEK_BUN</code>（Bun 可执行文件的路径）；</li><li>PATH 中的 <code>bun</code>；</li><li><code>~/.bun/bin/bun</code>（Windows 为 <code>bun.exe</code>）。</li></ol><p>没有 Bun 时从 <a href="https://bun.sh" target="_blank" rel="noreferrer">bun.sh</a> 安装，或设置 <code>NEK_INSTALL_BUN=1</code> 后重新运行安装脚本。</p></li><li><p><strong>源码安装</strong>的 nek（安装脚本装的就是）。新界面位于 <code>packages/opentui</code>。</p></li><li><p>支持真彩色和备用屏幕的终端。终端支持时会使用 Kitty 键盘协议。</p></li></ul><h2 id="启动" tabindex="-1">启动 <a class="header-anchor" href="#启动" aria-label="Permalink to &quot;启动&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ui</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opentui</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ui</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opentui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                          # 继续上次的会话</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ui</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opentui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sonnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;解释一下这个仓库&quot;</span></span></code></pre></div><p>所有交互模式的参数都可用（<code>-c</code>、<code>-r</code>、<code>--session</code>、<code>--model</code>、<code>@文件</code>、初始消息、<code>--verbose</code> 等）。<code>--ui opentui</code> 不能与 <code>--mode</code> 或 <code>--print</code> 同时使用。</p><p>它的工作方式：Node 启动器解析参数、找到 Bun，然后用 Bun 重新运行同一个 <code>main()</code>，只是把交互界面换成 OpenTUI 版本。因此会话、设置、扩展、启动提示、print/RPC 模式的行为与平时完全一致，agent 和界面在同一个 Bun 进程里运行。</p><h2 id="外观" tabindex="-1">外观 <a class="header-anchor" href="#外观" aria-label="Permalink to &quot;外观&quot;">​</a></h2><p>主题跟随 <code>--use-theme</code> 或 <code>theme</code> 设置（内置的 <code>dark</code>/<code>light</code> 或自定义主题）。界面从主题的页面背景派生出分层背景：对话记录（底层）、状态栏（面板）、输入框（凸起）、对话框和提示（浮层，圆角边框）。次要文字使用主题的 muted 和 dim 颜色，链接和 Web Search 行使用主题的链接蓝色（<code>mdLink</code>）。</p><h2 id="按键" tabindex="-1">按键 <a class="header-anchor" href="#按键" aria-label="Permalink to &quot;按键&quot;">​</a></h2><p>所有按键来自可配置的 <code>keybindings.json</code>，与原界面相同，<code>/hotkeys</code> 列出当前生效的绑定。默认值（括号内为 Windows/WSL 的替代键）：</p><table tabindex="0"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>发送。运行中：排队一条插话；压缩中：排队到压缩之后</td></tr><tr><td><code>Alt+Enter</code>（<code>Ctrl+Q</code>）</td><td>排队一条追加消息</td></tr><tr><td><code>Shift+Enter</code></td><td>换行</td></tr><tr><td><code>Alt+↑</code>（<code>Alt+Q</code>）</td><td>把排队的消息全部移回输入框</td></tr><tr><td><code>Esc</code></td><td>中止当前运行（排队消息回到输入框）、取消 bash、退出 bash 模式；输入框为空时按两次打开 <code>/tree</code> 或 <code>/fork</code></td></tr><tr><td><code>Ctrl+C</code></td><td>清空输入框；按两次退出</td></tr><tr><td><code>Ctrl+D</code></td><td>输入框为空时退出</td></tr><tr><td><code>Ctrl+Z</code></td><td>挂起（Windows 不支持）</td></tr><tr><td><code>Ctrl+O</code></td><td>展开/折叠工具输出、启动帮助和已加载资源</td></tr><tr><td><code>Ctrl+T</code></td><td>显示/隐藏思考内容</td></tr><tr><td><code>Shift+Tab</code></td><td>循环切换思考等级</td></tr><tr><td><code>Ctrl+P</code>、<code>Shift+Ctrl+P</code>（<code>Alt+P</code>）</td><td>下一个 / 上一个模型</td></tr><tr><td><code>Ctrl+L</code></td><td>模型选择器</td></tr><tr><td><code>Ctrl+G</code></td><td>用外部编辑器编辑提示词</td></tr><tr><td><code>Ctrl+V</code>（<code>Alt+V</code>）</td><td>从剪贴板粘贴图片（剪贴板是文字时粘贴文字）</td></tr><tr><td><code>/</code>、<code>!</code>、<code>!!</code>、<code>@</code></td><td>命令、bash、不进上下文的 bash、文件路径补全</td></tr><tr><td><code>PgUp</code> / <code>PgDn</code></td><td>滚动对话记录</td></tr><tr><td><code>Home</code> / <code>End</code></td><td>跳到开头 / 最新消息</td></tr><tr><td><code>Ctrl+↑</code> / <code>Ctrl+↓</code></td><td>上一条 / 下一条你的消息</td></tr><tr><td><code>Ctrl+Shift+F</code>（<code>Ctrl+F</code>）</td><td>搜索对话记录</td></tr></tbody></table><p>鼠标：滚轮滚动对话记录；拖选文字并在 <code>fullscreenCopyOnSelect</code> 开启时自动复制；右键粘贴到输入框。滚到上方后不再跟随新输出，并显示“跳到最新消息”按钮。</p><h2 id="普通模式" tabindex="-1">普通模式 <a class="header-anchor" href="#普通模式" aria-label="Permalink to &quot;普通模式&quot;">​</a></h2><p><code>tuiMode: &quot;regular&quot;</code> 或 <code>--tui-mode regular</code> 时，对话保留在终端自己的回滚记录里。OpenTUI 以 split-footer 模式运行：只重绘输入框及以下的区域，对话块在内容不再变化后写到上方。流式回复、运行中的工具、运行中的 <code>!</code> 命令和最新状态行在完成前一直停留在输入框上方。</p><p>已经进入回滚记录的输出无法修改。需要改变时（终端宽度、主题、工具输出展开、思考内容显示、重建对话、关闭对话框），会清屏并清空回滚记录，然后重新写出对话。普通模式下没有鼠标、对话滚动键和对话搜索，用终端自己的滚动和搜索。</p><h2 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h2><ul><li><strong>普通模式重绘</strong>：重放会重写整段对话；比屏幕高的流式回复在完成前只显示最新的几行。运行中从全屏切到普通模式后，退出时会清除可见屏幕。</li><li><strong>自动明暗主题</strong>暂时无法通过 OpenTUI 查询终端背景，会使用默认外观。</li><li><strong>终端进度</strong>（OSC 9;4）写在 OpenTUI 帧输出之外，不忽略未知 OSC 序列的终端可能显示杂字符。</li><li><strong>输入法</strong>：开启 <code>showHardwareCursor</code> 后终端光标跟随输入框光标，但 OpenTUI 没有输入法组合支持，预编辑文字不会内联显示。</li><li><strong>tmux</strong>：没有开启 <code>extended-keys</code>（以及 <code>extended-keys-format csi-u</code>）时，<code>Shift+Enter</code>、<code>Ctrl+Shift+F</code> 等组合键无法到达界面。</li><li><strong>字符宽度</strong>：少数 emoji 和东亚“宽度不明确”字符的宽度计算与原界面不同，可能差一格。</li><li>OpenTUI 仍是 1.0 之前的版本（<code>@opentui/core</code> 0.5.14）。</li></ul><p>逐项的功能对齐清单见仓库的 <code>packages/opentui/PARITY.md</code>。</p>`,21)])])}const k=t(c,[["render",a]]);export{u as __pageData,k as default};
